/* @catalog — generated by `npm run catalog:generate`; do not edit by hand.
 * Internal
 *   Functions: Location, renderWideShell, globalSearch, combobox
 *   Constants: searchPayload
 * Tests
 *   - wide layouts preview suggestions inline and keep the current route
 *   - arrow keys highlight a result and Enter opens it while recording the query
 *   - Enter without a highlighted suggestion opens full Search results and records the query
 *   - Escape closes the suggestions without leaving the field or recording history
 *   - an empty field offers recent searches that open full results
 *   - a MediaTrack suggestion starts playback and keeps the current route
 *   - the Search route keeps live page results and filters them by result type
 * @end-catalog */

import { QueryClient, QueryClientProvider } from '@tanstack/react-query';
import { render, screen, waitFor, within } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import { MemoryRouter, Route, Routes, useLocation } from 'react-router';

import { browserSessionQueryKey } from '../../api/session';
import { listenerCapabilitiesQueryKey } from '../../api/listenerCapabilities';
import { AppShell } from '../../app/AppShell';
import { playerStore } from '../../player';
import { SearchPage } from './SearchPage';
import { readSearchHistory, rememberSearchQuery } from './searchHistory';

const searchPayload = {
  query: 'Night',
  artists: [{ contentType: 'artist', id: 'artist-1', name: 'Night Ensemble', bio: '', artworkUrl: '' }],
  organizations: [],
  albums: [{
    contentType: 'album',
    id: 'album-1',
    title: 'Night Window',
    artworkUrl: '',
    artistNames: ['Night Ensemble'],
    releaseDate: { year: 2026 }
  }],
  audioTracks: [{
    contentType: 'audioTrack',
    id: 'track-1',
    title: 'Night Light',
    artworkUrl: '',
    artistNames: ['Night Ensemble'],
    albumId: 'album-1',
    albumTitle: 'Night Window',
    duration: '3:00',
    mediaType: 'audio',
    streamUrl: '/content/mediaTrack/stream/track-1'
  }]
};

/** Reports the router location so tests can prove the typeahead keeps the current route. */
const Location = () => <p data-testid="location">{`${useLocation().pathname}${useLocation().search}`}</p>;

/** Renders the shell on a wide layout (inline typeahead on) at the given route. */
const renderWideShell = (path = '/') => {
  vi.stubGlobal('matchMedia', vi.fn((query: string) => ({
    matches: query === '(min-width: 768px)',
    addEventListener: vi.fn(),
    removeEventListener: vi.fn()
  })));
  const fetchMock = vi.fn(async (input: RequestInfo | URL) => new Response(
    JSON.stringify(String(input).includes('/api/listener/v1/search') ? searchPayload : {}),
    { status: 200, headers: { 'Content-Type': 'application/json' } }
  ));
  vi.stubGlobal('fetch', fetchMock);
  const queryClient = new QueryClient({ defaultOptions: { queries: { retry: false } } });
  queryClient.setQueryData(browserSessionQueryKey, null);
  queryClient.setQueryData(listenerCapabilitiesQueryKey, { playlists: false });
  render(
    <QueryClientProvider client={queryClient}>
      <MemoryRouter initialEntries={[path]}>
        <Routes>
          <Route element={<AppShell />}>
            <Route index element={<p>Home route content</p>} />
            <Route path="/search" element={<SearchPage />} />
            <Route path="/albums/:albumId" element={<p>Album detail</p>} />
            <Route path="/artists/:artistId" element={<p>Artist detail</p>} />
          </Route>
        </Routes>
        <Location />
      </MemoryRouter>
    </QueryClientProvider>
  );
  return fetchMock;
};

// The shell field is lazy-loaded, so wait for it before querying inside it.
const globalSearch = () => screen.findByRole('search', { name: 'Global search' });
const combobox = async () => within(await globalSearch()).findByRole('combobox');

beforeEach(() => {
  localStorage.clear();
});

test('wide layouts preview suggestions inline and keep the current route', async () => {
  const user = userEvent.setup();
  renderWideShell();

  const field = await combobox();
  await user.type(field, 'Night');

  const listbox = await screen.findByRole('listbox', { name: 'Search suggestions' });
  expect(field).toHaveAttribute('aria-expanded', 'true');
  expect(field).toHaveAttribute('aria-controls', listbox.id);
  expect(await within(listbox).findByRole('option', { name: /Night Window/ })).toBeInTheDocument();
  expect(within(listbox).getByRole('option', { name: /Search for “Night”/ })).toBeInTheDocument();
  expect(screen.getByTestId('location')).toHaveTextContent(/^\/$/);
  expect(screen.getByText('Home route content')).toBeInTheDocument();
  expect(readSearchHistory(null)).toEqual([]);
});

test('arrow keys highlight a result and Enter opens it while recording the query', async () => {
  const user = userEvent.setup();
  renderWideShell();

  const field = await combobox();
  await user.type(field, 'Night');
  const listbox = await screen.findByRole('listbox', { name: 'Search suggestions' });
  const album = await within(listbox).findByRole('option', { name: /Night Window/ });

  // Option order: Search for, artist, album.
  await user.keyboard('{ArrowDown}{ArrowDown}{ArrowDown}');
  expect(field).toHaveAttribute('aria-activedescendant', album.id);
  expect(album).toHaveAttribute('aria-selected', 'true');
  await user.keyboard('{Enter}');

  await waitFor(() => expect(screen.getByTestId('location')).toHaveTextContent('/albums/album-1'));
  expect(readSearchHistory(null)).toEqual(['Night']);
  expect(screen.queryByRole('listbox')).not.toBeInTheDocument();
});

test('Enter without a highlighted suggestion opens full Search results and records the query', async () => {
  const user = userEvent.setup();
  renderWideShell();

  const field = await combobox();
  await user.type(field, 'Night');
  await screen.findByRole('listbox', { name: 'Search suggestions' });
  await user.keyboard('{Enter}');

  await waitFor(() => expect(screen.getByTestId('location')).toHaveTextContent('/search?q=Night'));
  expect(await screen.findByRole('heading', { name: 'Results for “Night”' })).toBeInTheDocument();
  expect(readSearchHistory(null)).toEqual(['Night']);
});

test('Escape closes the suggestions without leaving the field or recording history', async () => {
  const user = userEvent.setup();
  renderWideShell();

  const field = await combobox();
  await user.type(field, 'Night');
  await screen.findByRole('listbox', { name: 'Search suggestions' });
  await user.keyboard('{Escape}');

  expect(screen.queryByRole('listbox')).not.toBeInTheDocument();
  expect(field).toHaveAttribute('aria-expanded', 'false');
  expect(field).toHaveFocus();
  expect(readSearchHistory(null)).toEqual([]);
});

test('an empty field offers recent searches that open full results', async () => {
  const user = userEvent.setup();
  rememberSearchQuery(null, 'Piano');
  renderWideShell();

  await user.click(await combobox());
  const listbox = await screen.findByRole('listbox', { name: 'Search suggestions' });
  await user.click(within(listbox).getByRole('option', { name: /Piano/ }));

  await waitFor(() => expect(screen.getByTestId('location')).toHaveTextContent('/search?q=Piano'));
  expect(readSearchHistory(null)).toEqual(['Piano']);
});

test('a MediaTrack suggestion starts playback and keeps the current route', async () => {
  const user = userEvent.setup();
  const launch = vi.spyOn(playerStore, 'launchStandalone').mockResolvedValue();
  renderWideShell();

  await user.type(await combobox(), 'Night');
  const listbox = await screen.findByRole('listbox', { name: 'Search suggestions' });
  await user.click(await within(listbox).findByRole('option', { name: /Night Light/ }));

  await waitFor(() => expect(launch).toHaveBeenCalledWith(expect.objectContaining({ id: 'track-1' })));
  expect(screen.getByTestId('location')).toHaveTextContent(/^\/$/);
  expect(readSearchHistory(null)).toEqual(['Night']);
});

test('the Search route keeps live page results and filters them by result type', async () => {
  const user = userEvent.setup();
  renderWideShell('/search?q=Night');

  const field = await within(await globalSearch()).findByRole('searchbox');
  expect(field).not.toHaveAttribute('aria-expanded');
  expect(await screen.findByRole('heading', { name: 'Results for “Night”' })).toBeInTheDocument();

  const filters = screen.getByRole('group', { name: 'Search result types' });
  expect(within(filters).getByRole('button', { name: 'All' })).toHaveAttribute('aria-pressed', 'true');
  await user.click(within(filters).getByRole('button', { name: 'Albums' }));

  expect(within(filters).getByRole('button', { name: 'Albums' })).toHaveAttribute('aria-pressed', 'true');
  expect(screen.queryByRole('heading', { name: 'Artists' })).not.toBeInTheDocument();
  expect(screen.getByRole('heading', { name: 'Albums' })).toBeInTheDocument();
});
